              selected={organization.slug === slug}
              suffix={
                organization.slug === slug ? (
                  <Icon name="check" size="xs" onBackground="neutral-weak" />
                ) : undefined
              }
              onClick={(value) => {
                closeOverlay();
                select(value);
              }}
            />
          ))}
          {organizations.length === 0 && (
            <Text
              variant="body-default-s"
              onBackground="neutral-weak"
              paddingX="12"
              paddingY="8"
