        fillWidth
        gap="12"
        margin="0"
        padding="0"
        style={{ listStyle: "none" }}
        aria-label="Projects"
      >
        {projects.map((p) => {
          const isOpened = p.key === openKey;
          return (
            <Row
              as="li"
              key={p.key}
              background="page"
              border={isOpened ? "brand-alpha-strong" : true}
              borderWidth={isOpened ? 2 : 1}
